function exist(board: string[][], word: string): boolean {
  const m = board.length;
  const n = board[0].length;

  // Отсечение 1: в слове больше букв, чем клеток на доске
  if (word.length > m * n) return false;

  // Отсечение 2: какой-то буквы в слове больше, чем на доске
  const available = new Map<string, number>();
  for (const row of board) {
    for (const ch of row) available.set(ch, (available.get(ch) ?? 0) + 1);
  }
  const needed = new Map<string, number>();
  for (const ch of word) {
    needed.set(ch, (needed.get(ch) ?? 0) + 1);
    if (needed.get(ch)! > (available.get(ch) ?? 0)) return false;
  }

  // Отсечение 3: начинаем с более редкого конца слова — меньше стартовых веток
  let target = word;
  if ((available.get(word[0]) ?? 0) > (available.get(word[word.length - 1]) ?? 0)) {
    target = [...word].reverse().join('');
  }

  // dfs(r, c, i): можно ли составить target[i..], начиная с клетки (r, c)
  const dfs = (r: number, c: number, i: number): boolean => {
    if (r < 0 || r >= m || c < 0 || c >= n || board[r][c] !== target[i]) return false;
    // Совпала последняя буква — слово найдено
    if (i === target.length - 1) return true;

    // Помечаем клетку, чтобы не использовать её повторно в этом пути
    const saved = board[r][c];
    board[r][c] = '#';
    const found =
      dfs(r + 1, c, i + 1) || dfs(r - 1, c, i + 1) || dfs(r, c + 1, i + 1) || dfs(r, c - 1, i + 1);
    // Откат: возвращаем букву
    board[r][c] = saved;
    return found;
  };

  for (let r = 0; r < m; r++) {
    for (let c = 0; c < n; c++) {
      if (dfs(r, c, 0)) return true;
    }
  }
  return false;
}

// Время: O(m · n · 3^L) — из каждой клетки путь длины L, на каждом шаге до 3 новых направлений
// Память: O(L) на стек рекурсии (доска помечается на месте)
